CREATE TABLE projects (
    project_id INTEGER NOT NULL,
    owner_id INTEGER NOT NULL REFERENCES accounts ON DELETE CASCADE,
    slug TEXT NOT NULL,
    CONSTRAINT projects_pkey PRIMARY KEY (owner_id, project_id),
    UNIQUE (owner_id, slug)
);

CREATE TABLE tasks (
    task_id BIGSERIAL PRIMARY KEY,
    owner_id INTEGER NOT NULL,
    project_id INTEGER NOT NULL,
    title TEXT NOT NULL,
    note TEXT,
    parent_id BIGINT REFERENCES tasks (task_id) ON DELETE SET NULL ON UPDATE NO ACTION,
    CONSTRAINT tasks_project_fkey FOREIGN KEY (owner_id, project_id)
        REFERENCES projects (owner_id, project_id) MATCH FULL ON UPDATE CASCADE ON DELETE RESTRICT
        DEFERRABLE INITIALLY DEFERRED
);

CREATE UNLOGGED TABLE IF NOT EXISTS audit_log (
    entry_id integer GENERATED BY DEFAULT AS IDENTITY,
    payload jsonb NULL,
    CONSTRAINT audit_payload_check CHECK (payload IS NOT NULL) NO INHERIT
);

CREATE INDEX ON tasks (title);
CREATE INDEX ON tasks (title);
CREATE INDEX ON ONLY tasks (lower(title));
CREATE UNIQUE INDEX tasks_owner_title ON tasks USING btree (owner_id, title) INCLUDE (note) WHERE note IS NOT NULL;
CREATE INDEX IF NOT EXISTS tasks_note_idx ON tasks (note);
